    (N'ENERGY_CONSUMPTION_CURRENT', 11, N'nvarchar', NULL, NULL, 64, 0),
    (N'TOTAL_FLOOR_AREA', 12, N'nvarchar', NULL, NULL, 16, 0),
    (N'3_YR_ENERGY_COST_CURRENT', 13, N'nvarchar', NULL, NULL, 64, 0),
    (N'3_YR_ENERGY_SAVINGS_POTENTIAL', 14, N'nvarchar', NULL, NULL, 64, 0),
    (N'CURRENT_ENERGY_EFFICIENCY', 15, N'nvarchar', NULL, NULL, 16, 0),
    (N'CURRENT_ENERGY_RATING', 16, N'nvarchar', NULL, NULL, 16, 0),
    (N'POTENTIAL_ENERGY_EFFICIENCY', 17, N'nvarchar', NULL, NULL, 16, 0),
