    INSERT INTO #result
    SELECT N'epc_domestic', N'columns declared and in order', N'0 differences',
           CONVERT(nvarchar(200), COUNT(*)) + N' differences', COUNT(*), CASE WHEN COUNT(*) = 0 THEN 1 ELSE 0 END
    FROM (
        -- Bound to the one object being checked by OBJECT_ID, never by name alone.
        SELECT d.name FROM @declared d
        LEFT JOIN (SELECT c.name, c.column_id, t.name AS type_name, c.precision, c.scale, c.max_length, c.is_nullable
                   FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
                   WHERE c.object_id = OBJECT_ID(N'epc_domestic', N'U')) c
               ON c.name = d.name AND c.column_id = d.ordinal AND c.type_name = d.type_name
              AND (d.numeric_precision IS NULL
                   OR (c.precision = d.numeric_precision AND c.scale = d.numeric_scale))
              AND (d.max_length IS NULL OR c.max_length = d.max_length)
              AND c.is_nullable = d.is_nullable
        WHERE c.name IS NULL
        UNION ALL
        SELECT c.name FROM sys.columns c
        WHERE c.object_id = OBJECT_ID(N'epc_domestic', N'U')
          AND c.name NOT IN (SELECT name FROM @declared)
    ) AS differences;

    -- 2. The natural key: the digest is order independent, so a duplicated row and a missing
    -- one can cancel out.
    INSERT INTO #result
    SELECT N'epc_domestic', N'natural key [epc_release], [source_year], [source_row] unique and not null', N'0 offending rows',
           CONVERT(nvarchar(200), COUNT_BIG(*)) + N' offending rows', COUNT_BIG(*),
           CASE WHEN COUNT_BIG(*) = 0 THEN 1 ELSE 0 END
    FROM (SELECT [epc_release], [source_year], [source_row] FROM epc_domestic GROUP BY [epc_release], [source_year], [source_row] HAVING COUNT_BIG(*) > 1) AS duplicates;

    -- 3. Reserved framing characters in the text columns.
    INSERT INTO #result
    SELECT N'epc_domestic', N'no reserved framing characters in text', N'0 rows',
           CONVERT(nvarchar(200), COUNT_BIG(*)) + N' rows', COUNT_BIG(*),
           CASE WHEN COUNT_BIG(*) = 0 THEN 1 ELSE 0 END
    FROM epc_domestic
    WHERE DATALENGTH(REPLACE(REPLACE([epc_release] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([epc_release])
       OR DATALENGTH(REPLACE(REPLACE([HISTORIC] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([HISTORIC])
       OR DATALENGTH(REPLACE(REPLACE([BUILDING_REFERENCE_NUMBER] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([BUILDING_REFERENCE_NUMBER])
       OR DATALENGTH(REPLACE(REPLACE([OSG_REFERENCE_NUMBER] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([OSG_REFERENCE_NUMBER])
       OR DATALENGTH(REPLACE(REPLACE([POSTCODE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([POSTCODE])
       OR DATALENGTH(REPLACE(REPLACE([INSPECTION_DATE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([INSPECTION_DATE])
       OR DATALENGTH(REPLACE(REPLACE([TYPE_OF_ASSESSMENT] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([TYPE_OF_ASSESSMENT])
       OR DATALENGTH(REPLACE(REPLACE([LODGEMENT_DATE] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([LODGEMENT_DATE])
       OR DATALENGTH(REPLACE(REPLACE([ENERGY_CONSUMPTION_CURRENT] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ENERGY_CONSUMPTION_CURRENT])
       OR DATALENGTH(REPLACE(REPLACE([TOTAL_FLOOR_AREA] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([TOTAL_FLOOR_AREA])
       OR DATALENGTH(REPLACE(REPLACE([3_YR_ENERGY_COST_CURRENT] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([3_YR_ENERGY_COST_CURRENT])
       OR DATALENGTH(REPLACE(REPLACE([3_YR_ENERGY_SAVINGS_POTENTIAL] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([3_YR_ENERGY_SAVINGS_POTENTIAL])
       OR DATALENGTH(REPLACE(REPLACE([CURRENT_ENERGY_EFFICIENCY] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CURRENT_ENERGY_EFFICIENCY])
       OR DATALENGTH(REPLACE(REPLACE([CURRENT_ENERGY_RATING] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CURRENT_ENERGY_RATING])
       OR DATALENGTH(REPLACE(REPLACE([POTENTIAL_ENERGY_EFFICIENCY] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([POTENTIAL_ENERGY_EFFICIENCY])
       OR DATALENGTH(REPLACE(REPLACE([POTENTIAL_ENERGY_RATING] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([POTENTIAL_ENERGY_RATING])
       OR DATALENGTH(REPLACE(REPLACE([ENVIRONMENT_IMPACT_CURRENT] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ENVIRONMENT_IMPACT_CURRENT])
       OR DATALENGTH(REPLACE(REPLACE([CURRENT_ENVIRONMENTAL_RATING] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CURRENT_ENVIRONMENTAL_RATING])
       OR DATALENGTH(REPLACE(REPLACE([ENVIRONMENT_IMPACT_POTENTIAL] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ENVIRONMENT_IMPACT_POTENTIAL])
       OR DATALENGTH(REPLACE(REPLACE([POTENTIAL_ENVIRONMENTAL_RATING] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([POTENTIAL_ENVIRONMENTAL_RATING])
       OR DATALENGTH(REPLACE(REPLACE([CO2_EMISS_CURR_PER_FLOOR_AREA] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([CO2_EMISS_CURR_PER_FLOOR_AREA])
       OR DATALENGTH(REPLACE(REPLACE([IMPROVEMENTS] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([IMPROVEMENTS])
       OR DATALENGTH(REPLACE(REPLACE([WALL_DESCRIPTION] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([WALL_DESCRIPTION])
       OR DATALENGTH(REPLACE(REPLACE([WALL_ENERGY_EFF] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([WALL_ENERGY_EFF])
       OR DATALENGTH(REPLACE(REPLACE([WALL_ENV_EFF] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([WALL_ENV_EFF])
       OR DATALENGTH(REPLACE(REPLACE([ROOF_DESCRIPTION] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ROOF_DESCRIPTION])
       OR DATALENGTH(REPLACE(REPLACE([ROOF_ENERGY_EFF] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ROOF_ENERGY_EFF])
       OR DATALENGTH(REPLACE(REPLACE([ROOF_ENV_EFF] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ROOF_ENV_EFF])
       OR DATALENGTH(REPLACE(REPLACE([FLOOR_DESCRIPTION] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([FLOOR_DESCRIPTION])
       OR DATALENGTH(REPLACE(REPLACE([FLOOR_ENERGY_EFF] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([FLOOR_ENERGY_EFF])
       OR DATALENGTH(REPLACE(REPLACE([FLOOR_ENV_EFF] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([FLOOR_ENV_EFF])
       OR DATALENGTH(REPLACE(REPLACE([WINDOWS_DESCRIPTION] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([WINDOWS_DESCRIPTION])
       OR DATALENGTH(REPLACE(REPLACE([WINDOWS_ENERGY_EFF] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([WINDOWS_ENERGY_EFF])
       OR DATALENGTH(REPLACE(REPLACE([WINDOWS_ENV_EFF] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([WINDOWS_ENV_EFF])
       OR DATALENGTH(REPLACE(REPLACE([MAINHEAT_DESCRIPTION] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([MAINHEAT_DESCRIPTION])
       OR DATALENGTH(REPLACE(REPLACE([MAINHEAT_ENERGY_EFF] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([MAINHEAT_ENERGY_EFF])
       OR DATALENGTH(REPLACE(REPLACE([MAINHEAT_ENV_EFF] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([MAINHEAT_ENV_EFF])
