           ISNULL([datazone_2011_status], NCHAR(0)),
           ISNULL(CONVERT(varchar(10), [inspection_date_parsed], 23), NCHAR(0)),
           ISNULL(CONVERT(varchar(10), [lodgement_date_parsed], 23), NCHAR(0)),
           ISNULL(CONVERT(varchar(19), [created_at_parsed], 120), NCHAR(0)),
           ISNULL(CONVERT(varchar(1), [historic_flag]), NCHAR(0)),
           ISNULL(CONVERT(varchar(20), [current_energy_efficiency_int]), NCHAR(0)),
           ISNULL(CONVERT(varchar(20), [potential_energy_efficiency_int]), NCHAR(0)),
           ISNULL(CONVERT(varchar(20), [environment_impact_current_int]), NCHAR(0)),
           ISNULL(CONVERT(varchar(20), [environment_impact_potential_int]), NCHAR(0)),
           ISNULL(CONVERT(varchar(20), [total_floor_area_int]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [energy_consumption_current_num]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [co2_emissions_current_num]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [co2_emiss_curr_per_floor_area_num]), NCHAR(0))) COLLATE Latin1_General_100_BIN2_UTF8)), 1, 8)))) AS total
        FROM epc_domestic) AS q
    WHERE e.name = N'epc_domestic';
END

-- ============================================================================================
-- The result. A skipped check is not a pass, so an absent row fails the count below.
-- ============================================================================================
SELECT table_name, check_name, expected, actual, difference,
       CASE passed WHEN 1 THEN 'pass' ELSE 'FAIL' END AS outcome
FROM #result ORDER BY table_name, check_name;

DECLARE @failed int = (SELECT COUNT(*) FROM #result WHERE passed = 0);
DECLARE @ran int = (SELECT COUNT(*) FROM #result);
IF @failed > 0 OR @ran <> 5
    THROW 51000, 'The imported table does not match the build: see the result above.', 1;
